using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// Spawns enemies at the start of the path generated by TowerGridPathSpawner
/// and sends them along it. Runs after the path spawner so the path exists.
/// Each spawn randomly picks an enemy from the configured list (weighted).
[DefaultExecutionOrder(200)]
public class PathEnemySpawner : MonoBehaviour
{
    [Serializable]
    public class EnemyEntry
    {
        public GameObject prefab;
        [Tooltip("Relative chance of being picked. 0 = never spawns.")]
        [Min(0f)] public float weight = 1f;
    }

    [Header("References")]
    [SerializeField] TowerGrid grid;
    [SerializeField] TowerGridPathSpawner pathSource;

    [Header("Enemy Pool")]
    [Tooltip("Each spawn randomly picks one of these, weighted by 'weight'.")]
    [SerializeField] List<EnemyEntry> enemyPool = new List<EnemyEntry>();

    [Header("Spawning")]
    [SerializeField] int enemyCount = 5;
    [SerializeField] float spawnInterval = 1.5f;     // seconds between enemies
    [SerializeField] float startDelay = 1f;
    [Tooltip("Lift enemies above the path objects, along the grid's up axis (meters).")]
    [SerializeField] float heightOffset = 0.05f;

    void Start()
    {
        if (grid == null) grid = FindAnyObjectByType<TowerGrid>();
        if (pathSource == null) pathSource = FindAnyObjectByType<TowerGridPathSpawner>();

        if (grid == null || pathSource == null)
        {
            Debug.LogError("PathEnemySpawner: missing grid or path spawner.", this);
            return;
        }

        if (GetTotalWeight() <= 0f)
        {
            Debug.LogError("PathEnemySpawner: enemy pool is empty or has no valid prefabs with weight > 0.", this);
            return;
        }

        StartCoroutine(SpawnRoutine());
    }

    IEnumerator SpawnRoutine()
    {
        List<Vector3> waypoints = BuildWaypoints();
        if (waypoints.Count < 2)
        {
            Debug.LogWarning("PathEnemySpawner: no path available to follow.", this);
            yield break;
        }

        yield return new WaitForSeconds(startDelay);

        for (int i = 0; i < enemyCount; i++)
        {
            GameObject prefab = PickRandomEnemy();
            if (prefab != null)
            {
                GameObject enemy = Instantiate(prefab, waypoints[0], grid.transform.rotation);

                var follower = enemy.GetComponent<PathEnemyFollower>();
                if (follower == null) follower = enemy.AddComponent<PathEnemyFollower>();
                follower.Initialize(waypoints, grid.transform.up);
            }

            yield return new WaitForSeconds(spawnInterval);
        }
    }

    float GetTotalWeight()
    {
        float total = 0f;
        foreach (var e in enemyPool)
            if (e != null && e.prefab != null && e.weight > 0f)
                total += e.weight;
        return total;
    }

    GameObject PickRandomEnemy()
    {
        float total = GetTotalWeight();
        if (total <= 0f) return null;

        float roll = UnityEngine.Random.value * total;
        float cumulative = 0f;
        GameObject lastValid = null;

        foreach (var e in enemyPool)
        {
            if (e == null || e.prefab == null || e.weight <= 0f) continue;
            lastValid = e.prefab;
            cumulative += e.weight;
            if (roll <= cumulative) return e.prefab;
        }

        return lastValid; // guards against floating-point edge cases
    }

    List<Vector3> BuildWaypoints()
    {
        var points = new List<Vector3>();
        Vector3 lift = grid.transform.up * heightOffset;

        foreach (var cell in pathSource.Path)
            if (grid.TryGetPoint(cell, out Vector3 p))
                points.Add(p + lift);

        return points;
    }
}